const cfg = $('Config').first().json;
const startedAt = Date.now();
const maxN = Number(cfg.max_por_execucao ?? 20);
const items = $input.all().map((i) => i.json);
let list = [];
if (items.length === 1 && Array.isArray(items[0])) list = items[0];
else if (items.length === 1 && Array.isArray(items[0]?.data)) list = items[0].data;
else list = items.filter((r) => r && r.id);

const fila = [];
let semExternal = 0;
for (const p of list) {
  if (!p?.external_id) { semExternal += 1; continue; }
  if (fila.length >= maxN) break;
  fila.push({
    product_uuid: p.id,
    bling_id: String(p.external_id),
    name: p.name ?? null,
  });
}

return [{
  json: {
    ...cfg,
    started_at: new Date(startedAt).toISOString(),
    started_ms: startedAt,
    skip: fila.length === 0,
    motivo: fila.length === 0 ? 'nenhum_produto_sem_gtin' : null,
    candidatos_lidos: list.length,
    sem_external_id: semExternal,
    fila_count: fila.length,
    fila,
  },
}];

const meta = $('Montar fila').first().json;
const cfg = $('Config').first().json;
return (meta.fila || []).map((p) => ({
  json: {
    product_uuid: p.product_uuid,
    bling_id: p.bling_id,
    name: p.name,
    bling_base_url: cfg.bling_base_url,
    supabase_url: cfg.supabase_url,
  },
}));

const cfg = $('Config').first().json;
const meta = $('Montar fila').first().json;
const expand = $('Expand fila').all();
const detalhes = $('BLING - Detalhe').all();

/** Marcador: tira da fila (gtin NOT NULL) sem ser EAN real. Matching 011 ignora SEM GTIN. */
const NO_GTIN_MARKER = 'SEM GTIN';

/** Prioridade: gtin → gtinEmbalagem. Trim; ignora vazio / SEM GTIN. */
function extractGtin(data) {
  const candidates = [data?.gtin, data?.gtinEmbalagem, data?.tributacao?.gtin, data?.tributacao?.gtinEmbalagem];
  for (const raw of candidates) {
    if (raw === undefined || raw === null) continue;
    const s = String(raw).trim();
    if (!s) continue;
    if (/^sem\s*gtin$/i.test(s)) continue;
    return s;
  }
  return null;
}

const patches = [];
let analisados = 0;
let gtinEncontrados = 0;
let semGtin = 0;
let erros = 0;
let exemploGtin = null;
let exemploKeys = null;

for (let i = 0; i < detalhes.length; i++) {
  const d = detalhes[i];
  const item = expand[i]?.json;
  if (!item?.product_uuid) continue;
  analisados += 1;

  const body = d.json;
  if (body?.error || (body?.status && body.status >= 400)) {
    erros += 1;
    continue;
  }
  const data = body.data ?? body;
  if (!data || typeof data !== 'object' || data.error) {
    erros += 1;
    continue;
  }

  if (!exemploKeys) {
    exemploKeys = Object.keys(data).slice(0, 30).join(',');
  }

  const gtin = extractGtin(data);
  if (!gtin) {
    // 200 OK sem GTIN no BLING → marca e sai da fila (não reprocessar eternamente)
    semGtin += 1;
    patches.push({
      product_uuid: item.product_uuid,
      bling_id: item.bling_id,
      gtin: NO_GTIN_MARKER,
      is_marker: true,
    });
    continue;
  }

  gtinEncontrados += 1;
  if (!exemploGtin) exemploGtin = gtin;
  patches.push({
    product_uuid: item.product_uuid,
    bling_id: item.bling_id,
    gtin,
    is_marker: false,
  });
}

return [{
  json: {
    supabase_url: cfg.supabase_url,
    skip_patch: patches.length === 0,
    patches,
    analisados,
    gtin_encontrados: gtinEncontrados,
    sem_gtin: semGtin,
    sem_gtin_marcados: semGtin,
    erros,
    exemplo_gtin: exemploGtin,
    exemplo_keys: exemploKeys,
    fila_count: meta.fila_count ?? 0,
    candidatos_lidos: meta.candidatos_lidos ?? 0,
    started_ms: meta.started_ms,
    started_at: meta.started_at,
  },
}];

const row = $('Extrair GTIN').first().json;
const cfg = $('Config').first().json;
return (row.patches || []).map((p) => ({
  json: {
    url: cfg.supabase_url + '/rest/v1/products?id=eq.' + p.product_uuid,
    body: { gtin: p.gtin },
    product_uuid: p.product_uuid,
    gtin: p.gtin,
    skip_patch: false,
  },
}));

const meta = $('Montar fila').first().json;
const startedMs = Number(meta.started_ms ?? Date.now());
const elapsedMs = Date.now() - startedMs;

let out = {
  status: 'ok',
  patch: '011.1b',
  workflow: 'backfill-gtin',
  candidatos_lidos: meta.candidatos_lidos ?? 0,
  fila_count: meta.fila_count ?? 0,
  analisados: 0,
  gtin_encontrados: 0,
  gtin_gravados: 0,
  sem_gtin: 0,
  sem_gtin_marcados: 0,
  erros: 0,
  patches_fail: 0,
  exemplo_gtin: null,
  exemplo_keys: null,
  started_at: meta.started_at ?? null,
  finished_at: new Date().toISOString(),
  tempo_total_ms: elapsedMs,
  tempo_total_s: Math.round(elapsedMs / 1000),
  max_por_execucao: meta.max_por_execucao ?? null,
  lote_size: meta.lote_size ?? null,
  bling_interval_ms: meta.bling_interval_ms ?? null,
};

if (meta.skip) {
  return [{ json: { ...out, motivo: meta.motivo || 'fila_vazia' } }];
}

try {
  const ex = $('Extrair GTIN').first().json;
  out.analisados = ex.analisados ?? 0;
  out.gtin_encontrados = ex.gtin_encontrados ?? 0;
  out.sem_gtin = ex.sem_gtin ?? 0;
  out.sem_gtin_marcados = ex.sem_gtin_marcados ?? ex.sem_gtin ?? 0;
  out.erros = ex.erros ?? 0;
  out.exemplo_gtin = ex.exemplo_gtin ?? null;
  out.exemplo_keys = ex.exemplo_keys ?? null;
  out.gtin_gravados = ex.gtin_encontrados ?? 0;

  if (ex.skip_patch) {
    return [{ json: { ...out, motivo: 'detalhe_sem_gtin_ou_erros' } }];
  }
} catch (e) {}

try {
  let ok = 0;
  let fail = 0;
  for (const it of $('Supabase - Patch GTIN').all()) {
    const j = it.json;
    const status = Number(j.statusCode ?? j.status ?? 0);
    if (status >= 200 && status < 300) ok += 1;
    else if (!status && !j.error) ok += 1;
    else fail += 1;
  }
  out.patches_ok = ok;
  out.patches_fail = fail;
  // gravados reais ≈ encontrados; marcadores SEM GTIN também entram em patches_ok
  out.gtin_gravados = out.gtin_encontrados;
} catch (e) {}

return [{ json: out }];
